// Source compiler adapter. Third-party implementation and notices live in runtime-assets/.
const VERSION_PATH = 'cpp/browsercc-0.1.1/';
const OUTPUT_LIMIT = 65536;
let environment;

async function compressedAsset(url) {
  let cache;
  try { cache = await caches.open('code-typer-idle:runtime:cpp-browsercc-0.1.1'); } catch { /* storage is optional */ }
  let response = await cache?.match(url);
  if (!response) {
    response = await fetch(url);
    if (!response.ok) throw new Error(`Compiler asset HTTP ${response.status}`);
    const bytes = await response.arrayBuffer();
    if (cache) {
      try { await cache.put(url, new Response(bytes)); } catch { /* quota must not prevent compilation */ }
    }
    response = new Response(bytes);
  }
  const bytes = new Uint8Array(await response.arrayBuffer());
  // Some hosts transparently decode .gz responses. Accept that without decompressing twice.
  if (bytes[0] !== 0x1f || bytes[1] !== 0x8b) return bytes.buffer;
  return new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();
}

function instantiate(module) {
  return (imports, receive) => {
    WebAssembly.instantiate(module, imports).then(instance => receive(instance, module));
  };
}

function outputArgs(line) {
  const args = [...line.matchAll(/"((?:[^"\\]|\\.)*)"/g)].map(match => JSON.parse(match[0])).slice(1);
  const index = args.indexOf('-o');
  if (index < 0 || !args[index + 1]) throw new Error('Compiler driver did not provide an output path');
  return { args, output: args[index + 1] };
}

async function prepare(baseUrl) {
  const root = new URL(VERSION_PATH, String(baseUrl).replace(/\/?$/, '/'));
  const [library, wasi, clang, lld, sysroot] = await Promise.all([
    import(new URL('index.js', root).href),
    import(new URL('wasi/index.js', root).href),
    compressedAsset(new URL('clang.wasm.gz', root).href).then(bytes => WebAssembly.compile(bytes)),
    compressedAsset(new URL('lld.wasm.gz', root).href).then(bytes => WebAssembly.compile(bytes)),
    compressedAsset(new URL('sysroot.tar.gz', root).href),
  ]);
  let driverOutput = '';
  const driver = await library.Clang({ thisProgram: 'clang++', instantiateWasm: instantiate(clang),
    printErr: text => { driverOutput += text + '\n'; }, print: () => {} });
  driver.FS.writeFile('main.cpp', '');
  driver.FS.mkdirTree('/lib/wasm32-wasi');
  driver.FS.mkdirTree('/include/c++/v1');
  driver.FS.writeFile('/lib/wasm32-wasi/crt1-command.o', new Uint8Array());
  driver.FS.writeFile('/lib/wasm32-wasi/crt1-reactor.o', new Uint8Array());
  const exit = driver.callMain(['main.cpp', '-O2', '-std=c++20', '-fno-exceptions', '-fno-color-diagnostics', '-###']);
  if (exit !== 0) throw new Error(driverOutput || `Compiler driver exited ${exit}`);
  const lines = driverOutput.split('\n');
  const compile = outputArgs(lines.find(line => line.includes('"-cc1"')) || '');
  const link = outputArgs(lines.find(line => line.includes('wasm-ld')) || '');
  return { library, wasi, clang, lld, sysroot, compile, link };
}

/** baseUrl is the absolute URL of the shared runtime-assets/ directory. */
export async function initialize(baseUrl) {
  if (!environment) environment = prepare(baseUrl).catch(error => { environment = undefined; throw error; });
  await environment;
}

/** source contains the learner function and the exercise's main/test harness. */
export async function execute(source) {
  if (!environment) throw new Error('C++ runner is not initialized');
  const env = await environment;
  let stderr = '', stdout = '', outputTruncated = false, phase = 'compile';
  const appendError = text => {
    outputTruncated ||= stderr.length + text.length + 1 > OUTPUT_LIMIT;
    stderr = (stderr + text + '\n').slice(0, OUTPUT_LIMIT);
  };
  try {
    const compiler = await env.library.Clang({ thisProgram: 'clang++', instantiateWasm: instantiate(env.clang),
      printErr: appendError, print: appendError });
    compiler.FS.writeFile('main.cpp', source);
    env.library.setUpSysroot(compiler, env.sysroot);
    // Emscripten callMain prepends argv[0] to its input array in place.
    // Keep the cached invocation reusable across exercise submissions.
    if (compiler.callMain([...env.compile.args]) !== 0) {
      return { stdout, stderr, error: 'compile-error', errorKind: 'compile', outputTruncated, diagnostics: [{ severity: 'error', message: stderr }] };
    }
    const object = compiler.FS.readFile(env.compile.output, { encoding: 'binary' });
    const linker = await env.library.LLD({ thisProgram: 'wasm-ld', instantiateWasm: instantiate(env.lld),
      printErr: appendError, print: appendError });
    env.library.setUpSysroot(linker, env.sysroot);
    const parent = env.compile.output.split('/').slice(0, -1).join('/');
    if (parent) linker.FS.mkdirTree(parent);
    linker.FS.writeFile(env.compile.output, object);
    if (linker.callMain([...env.link.args]) !== 0) {
      return { stdout, stderr, error: 'compile-error', errorKind: 'compile', outputTruncated, diagnostics: [{ severity: 'error', message: stderr }] };
    }
    const bytes = linker.FS.readFile(env.link.output, { encoding: 'binary' });
    const module = await WebAssembly.compile(bytes);
    phase = 'runtime';
    const outputDecoder = new TextDecoder(), errorDecoder = new TextDecoder();
    const input = new env.wasi.OpenFile(new env.wasi.File(new Uint8Array()));
    const output = new env.wasi.ConsoleStdout(data => {
      const text = outputDecoder.decode(data, { stream: true });
      outputTruncated ||= stdout.length + text.length > OUTPUT_LIMIT;
      stdout = (stdout + text).slice(0, OUTPUT_LIMIT);
    });
    const errors = new env.wasi.ConsoleStdout(data => {
      const text = errorDecoder.decode(data, { stream: true });
      outputTruncated ||= stderr.length + text.length > OUTPUT_LIMIT;
      stderr = (stderr + text).slice(0, OUTPUT_LIMIT);
    });
    const runtime = new env.wasi.WASI([], [], [input, output, errors]);
    const instance = await WebAssembly.instantiate(module, { wasi_snapshot_preview1: runtime.wasiImport });
    const code = runtime.start(instance);
    return code === 0 ? { stdout, stderr, outputTruncated } : { stdout, stderr, outputTruncated, error: `runtime-exit-${code}`, errorKind: 'runtime' };
  } catch (error) {
    return { stdout, stderr, outputTruncated, error: phase === 'compile' ? 'compile-error' : 'runtime-error', errorKind: phase, diagnostics: [{ severity: 'error', message: error instanceof Error ? error.message : String(error) }] };
  }
}
